/**
 *
 * @export
 * @interface EarningsItem
 */
export interface EarningsItem {
    /**
     * Date of earning release
     * @type {string}
     * @memberof EarningsItem
     */
    date: string;
    /**
     * Time of earning release, can be either of the following values: `Pre Market`, `After Hours`, `Time Not Supplied`
     * @type {string}
     * @memberof EarningsItem
     */
    time?: string;
    /**
     * Analyst estimate of the future company earning
     * @type {number}
     * @memberof EarningsItem
     */
    epsEstimate?: number;
    /**
     * Actual value of reported earning
     * @type {number}
     * @memberof EarningsItem
     */
    epsActual?: number;
    /**
     * Delta between `eps_actual` and `eps_estimate`
     * @type {number}
     * @memberof EarningsItem
     */
    difference?: number;
    /**
     * Surprise in the percentage of the `eps_actual` related to `eps_estimate`
     * @type {number}
     * @memberof EarningsItem
     */
    surprisePrc?: number;
}
/**
 * Check if a given object implements the EarningsItem interface.
 */
export declare function instanceOfEarningsItem(value: object): value is EarningsItem;
export declare function EarningsItemFromJSON(json: any): EarningsItem;
export declare function EarningsItemFromJSONTyped(json: any, ignoreDiscriminator: boolean): EarningsItem;
export declare function EarningsItemToJSON(json: any): EarningsItem;
export declare function EarningsItemToJSONTyped(value?: EarningsItem | null, ignoreDiscriminator?: boolean): any;
